import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address contract_address, address[] memory tos, uint[] memory vs) public {
        // We only care about calls that do not revert
        // The rule: if transfer returns, it returns true
        vm.assume(contract_address != address(0));
        vm.assume(contract_address != address(c));
        vm.assume(tos.length > 0);
        vm.assume(vs.length > 0);
        vm.assume(tos.length == vs.length);
        // Additional assumptions to ensure the external call does not revert
        // We need to assume the tos and vs are valid for the contract_address
